class Solution { public long maxScore(int[] nums1,int[] nums2,int k){Integer[] order=new Integer[nums1.length];for(int i=0;i<order.length;i++)order[i]=i;Arrays.sort(order,(a,b)->Integer.compare(nums2[b],nums2[a]));PriorityQueue<Integer> heap=new PriorityQueue<>();long sum=0,answer=0;for(int index:order){heap.offer(nums1[index]);sum+=nums1[index];if(heap.size()>k)sum-=heap.poll();if(heap.size()==k)answer=Math.max(answer,sum*nums2[index]);}return answer;} }
